import React from 'react';
import data from './worldDots.json';

/**
 * Dot-matrix world map (Natural Earth 1:110m, equirectangular, generated by
 * scripts/motion/make-dotmap.mjs). Each dot knows whether it is in the U.S.
 *  us / intl: 0..1 "lit" level for U.S. and non-U.S. dots.
 *  ripple:    when > 0, non-U.S. dots light in a wave spreading from the U.S.
 *             (`intl` then acts as the wave's progress 0..1).
 * Use `usPoint(x, y, w)` to aim a Camera at the United States.
 */
type Dots = {aspect: number; dots: [number, number, number][]};
const D = data as unknown as Dots;
const US_U = 0.2; // ~98°W on this projection
const US_V = 0.29; // ~39°N

export const mapHeight = (w: number) => w / D.aspect;
export const usPoint = (x: number, y: number, w: number): [number, number] => [x + US_U * w, y + US_V * mapHeight(w)];

export const WorldDotMap: React.FC<{
	x: number;
	y: number;
	w: number;
	us: number;
	intl: number;
	ripple?: boolean;
	litColor?: string;
	usColor?: string;
	offColor?: string;
	/** colour of U.S. dots when `us` is 0 (default offColor) — use a visible grey to show the U.S. dimmed rather than gone */
	usOffColor?: string;
	dotScale?: number;
	opacity?: number;
}> = ({x, y, w, us, intl, ripple = false, litColor = '#2CD47A', usColor, offColor = '#2B3038', usOffColor, dotScale = 1, opacity = 1}) => {
	const h = mapHeight(w);
	const step = w / 139; // dot pitch in px (2.6° grid over 360°)
	const r = step * 0.36 * dotScale;
	const lerp = (t: number, a: [number, number, number], b: [number, number, number]) =>
		`rgb(${Math.round(a[0] + (b[0] - a[0]) * t)},${Math.round(a[1] + (b[1] - a[1]) * t)},${Math.round(a[2] + (b[2] - a[2]) * t)})`;
	const hex = (s: string): [number, number, number] => [parseInt(s.slice(1, 3), 16), parseInt(s.slice(3, 5), 16), parseInt(s.slice(5, 7), 16)];
	const off = hex(offColor);
	const lit = hex(litColor);
	const usLit = hex(usColor ?? litColor);
	const usOff = hex(usOffColor ?? offColor);
	return (
		<svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{position: 'absolute', left: x, top: y, overflow: 'visible', opacity}}>
			{D.dots.map(([u, v, isUS], i) => {
				let t: number;
				if (isUS) t = us;
				else if (ripple) {
					const dist = Math.hypot((u - US_U) * D.aspect, v - US_V) / 2.2; // 0..~1
					t = Math.max(0, Math.min(1, (intl * 1.6 - dist) * 4));
				} else t = intl;
				return <circle key={i} cx={u * w} cy={v * h} r={r * (1 + 0.15 * t)} fill={lerp(t, isUS ? usOff : off, isUS ? usLit : lit)} />;
			})}
		</svg>
	);
};
